{
  "API_calls": [],
  "collected_information": {
    "environment_setup": {
      "python_versions": ["3.10", "3.11", "3.12"],
      "package_manager": "Poetry 1.8.2",
      "installation_commands": [
        "poetry env use <python-version>",
        "poetry install"
      ],
      "env_variables": ["OPENAI_API_KEY (from GitHub secrets)"]
    },
    "test_execution": {
      "unit_tests_command": "make unit_tests args=\"--splits ${matrix.splitCount} --group ${matrix.group}\"",
      "test_grouping": 5,
      "cli_tests": {
        "start_backend": "poetry run python -m langflow run --host 127.0.0.1 --port 7860 --backend-only &",
        "wait_for_api": "timeout 120 bash -c 'until curl -f http://127.0.0.1:7860/api/v1/auto_login; do sleep 5; done'",
        "teardown": "kill backend process and verify"
      },
      "test_runner_os": "ubuntu-latest",
      "cache": "Poetry dependencies cached between runs"
    },
    "documentation_summary": {
      "README.md": {
        "python_version_required": ">=3.10",
        "installation": [
          "python -m pip install langflow -U",
          "make install_frontend && make build_frontend && make install_backend"
        ],
        "run_app": "python -m langflow run",
        "env_file_example": ".env.example provided"
      },
      "CONTRIBUTING.md": {
        "poetry_version": ">=1.4",
        "nodejs_required": true,
        "dev_servers": {
          "backend": "make backend",
          "frontend": "make frontend"
        },
        "docker_dev": "docker compose up --build or make dev build=1"
      },
      "pyproject.toml": {
        "python_version": ">=3.10,<3.13",
        "dependencies": "Exact versions listed",
        "dev_dependencies": [
          "pytest ^8.2.0",
          "pytest-cov",
          "pytest-mock",
          "pytest-xdist",
          "pytest-asyncio",
          "pre-commit",
          "ruff",
          "mypy",
          "coverage"
        ],
        "pytest_config": {
          "testpaths": ["tests", "integration"],
          "markers": ["async_test", "api_key_required"],
          "coverage_exclude": ["integration", "tests/api_key_required"]
        }
      },
      "poetry.lock": {
        "locked_versions": "Exact versions with reproducibility assured"
      },
      ".github/workflows/python_test.yml": {
        "python_versions": ["3.10", "3.11", "3.12"],
        "poetry_version": "1.8.2",
        "env_variables": ["OPENAI_API_KEY"],
        "test_commands": [
          "make unit_tests args=\"--splits ${matrix.splitCount} --group ${matrix.group}\"",
          "CLI backend start and readiness check commands"
        ],
        "os": "ubuntu-latest",
        "cache": "Poetry dependencies"
      }
    }
  },
  "terminate": true
}
